// Имена компонентов/пропсов @jinx-ui/react взяты по типовому API библиотеки — сверьте с вашей версией пакета.
import { useState } from 'react';
import {
  Badge,
  Card,
  Divider,
  Field,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
  Title,
} from '@jinx-ui/react';

export type Theme = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_OPTIONS: ReadonlyArray<{ value: Theme; label: string }> = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: ReadonlyArray<{ value: FontFamily; label: string }> = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const MIN_SCALE = 80;
const MAX_SCALE = 140;

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...DEFAULTS,
    ...defaultValue,
  });

  const patch = (next: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const merged = { ...prev, ...next };
      onChange?.(merged);
      return merged;
    });
  };

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <Card padding="lg">
      <Stack direction="column" gap="lg">
        <Stack direction="row" align="center" gap="sm">
          <Title level={2}>Внешний вид</Title>
          <Badge variant="neutral">{themeLabel}</Badge>
        </Stack>

        <Field label="Тема" htmlFor="appearance-theme">
          <SegmentedControl
            id="appearance-theme"
            value={settings.theme}
            options={THEME_OPTIONS}
            onChange={(theme: Theme) => patch({ theme })}
          />
        </Field>

        <Field
          label="Масштаб интерфейса"
          htmlFor="appearance-scale"
          hint={`${MIN_SCALE}–${MAX_SCALE}%`}
        >
          <Stack direction="row" align="center" gap="md">
            <Slider
              id="appearance-scale"
              min={MIN_SCALE}
              max={MAX_SCALE}
              step={5}
              value={settings.scale}
              onChange={(scale: number) => patch({ scale })}
              style={{ flex: 1 }}
            />
            <Text
              variant="body"
              tone="muted"
              style={{ minWidth: 'var(--jx-size-12)', textAlign: 'right' }}
            >
              {settings.scale}%
            </Text>
          </Stack>
        </Field>

        <Switch
          checked={settings.dense}
          onChange={(dense: boolean) => patch({ dense })}
          label="Плотная вёрстка"
          description="Уменьшает отступы между элементами списков и форм."
        />

        <Divider />

        <Stack direction="column" gap="md">
          <Title level={3}>Ещё</Title>
          <Field label="Шрифт" htmlFor="appearance-font">
            <Select
              id="appearance-font"
              value={settings.font}
              options={FONT_OPTIONS}
              onChange={(font: FontFamily) => patch({ font })}
            />
          </Field>
        </Stack>
      </Stack>
    </Card>
  );
}

